package org.springframework.samples.petclinic.rest.validation;

import jakarta.validation.Constraint;
import jakarta.validation.Payload;
import java.lang.annotation.*;

/**
 * Validates that a telephone number contains exactly ten digits once every non-digit
 * character has been stripped. Non-digit separators (spaces, parentheses, dashes, ...)
 * are ignored, matching the create-time normalization performed by the mapper.
 */
